n}\n\n.btn-color:hover {\n  color:#fff;\n}\n","$font-primary:\n  Roboto, -apple-system, system-ui, BlinkMacSystemFont, \"Segoe UI\", \"Helvetica Neue\", Arial, sans-serif;\n$font-secondary: $font-primary;\n$font-size-base:              0.875rem;\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @Greyscale Colors\n// + @Bootstrap Color System\n// + @Default Colors\n// + @Inverted Colors\n// + @Others\n// + @Header Themes\n// + @Social Networks Colors\n\n// ---------------------------------------------------------\n// @Greyscale Colors\n// ---------------------------------------------------------\n\n// Colors below are ordered from lightest to darkest\n\n$grey-100             : #f9fafb;\n$grey-200             : #f2f3f5;\n$grey-300             : #e6eaf0;\n$grey-400             : #d3d9e3;\n$grey-500             : #b9c2d0;\n$grey-600             : #7c8695;\n$grey-700             : #72777a;\n$grey-800             : #565a5c;\n$grey-900             : #313435;\n\n$grey-colors-alt: (\n  grey-100 : #f9fafb,\n  grey-200 : #f2f3f5,\n  grey-300 : #e6eaf0,\n  grey-400 : #d3d9e3,\n  grey-500 : #b9c2d0,\n  grey-600 : #7c8695,\n  grey-700 : #72777a,\n  grey-800 : #565a5c,\n  grey-900 : #313435,\n);\n\n// ---------------------------------------------------------\n// @Bootstrap Color System\n// ---------------------------------------------------------\n\n$blue   : $md-blue-500;\n$indigo : $md-indigo-500;\n$purple : $md-purple-500;\n$pink   : $md-pink-500;\n$red    : $md-red-500;\n$orange : $md-orange-500;\n$yellow : $md-yellow-500;\n$green  : $md-green-500;\n$teal   : $md-teal-500;\n$cyan   : $md-cyan-500;\n\n// ---------------------------------------------------------\n// @Default Colors\n// ---------------------------------------------------------\n\n$default-danger       : #ff3c7e;\n$default-dark         : #313435;\n$default-grey         : #565a5c;\n$default-info         : #0f9aee;\n$defaul