x solid $border-color;\n  line-height: 0;\n  padding: 0 20px;\n  transition: all 0.2s ease;\n\n  a {\n    display: inline-block;\n    width: 100%;\n\n    .logo {\n      background-position: center left;\n      background-repeat: no-repeat;\n      display: inline-block;\n      min-height: calc(#{$header-height} - 1px);\n      width: 100%;\n      width: 70px;\n    }\n\n    .logo-text {\n      color: $grey-900;\n    }\n  }\n\n  .mobile-toggle {\n    display: none;\n    float: right;\n    font-size: 18px;\n    line-height: calc(#{$header-height} - 1px);\n\n    a {\n      color: $default-text-color;\n    }\n\n    @include to($breakpoint-md) {\n      display: inline-block;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      display: none;\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Sidebar Menu\n// ---------------------------------------------------------\n\n.sidebar-menu {\n  @include clearfix;\n  border-right: 1px solid $border-color;\n  height: calc(100vh - #{$header-height});\n  list-style: none;\n  margin: 0;\n  overflow: auto;\n  padding: 0;\n  position: relative;\n\n  .dropdown-toggle::after {\n    display: none;\n  }\n\n  .sidebar-link {\n    &.actived::before {\n      background: $md-blue-500;\n      border-radius: 50%;\n      content: '';\n      display: block;\n      height: 8px;\n      left: -4px;\n      position: absolute;\n      top: calc(50% - 4px);\n      width: 8px;\n    }\n  }\n\n  li {\n    position: relative;\n\n    &.dropdown {\n      .arrow {\n        font-size: 10px;\n        line-height: 40px;\n        position: absolute;\n        right: 30px;\n        transition: all 0.05s ease-in;\n\n        @include to($breakpoint-md) {\n          right: 25px;\n        }\n      }\n\n      &.open {\n        > a {\n          color: $default-dark;\n\n          .icon-holder {\n            color: $default-info;\n          }\n\n          > .arrow {\n            transform: rotate(90deg);\n          }\n        }\n\n        > .dropdown-menu {\n          display: block;\n\n          .dropdown-menu {\n            padding-left: 20px;\n          }\n\n          .arrow {\n            line-height: 25px;\n          }\n        }\n      }\n    }\n\n    a {\n      color: $default-text-color;\n      transition: all 0.3s ease;\n\n      &:hover,\n      &:focus {\n        color: $default-dark;\n        text-decoration: none;\n\n        .icon-holder {\n          color: $default-info;\n        }\n      }\n    }\n  }\n\n  > li {\n    &.dropdown {\n      ul {\n        &.dropdown-menu {\n          background-color: transparent;\n          border-radius: 0;\n          border: 0;\n          box-shadow: none;\n          float: none;\n          padding-left: 50px;\n          padding-top: 0;\n          position: relative;\n          width: 100%;\n\n          > li {\n            > a {\n              display: block;\n              padding: 10px 15px;\n\n              &:hover,\n              &:focus {\n                background-color: transparent;\n                color: $default-dark;\n              }\n            }\n\n            &.actived {\n              a {\n                color: $default-dark;\n              }\n            }\n          }\n        }\n      }\n    }\n\n    > a {\n      display: block;\n      font-size: 15px;\n      font-weight: 500;\n      padding: 5px 15px;\n      position: relative;\n      white-space: nowrap;\n\n      .icon-holder {\n        border-radius: 6px;\n        display: inline-block;\n        font-size: 17px;\n        height: 35px;\n        left: 0;\n        line-height: 35px;\n        margin-right: 14px;\n        position: relative;\n        text-align: center;\n        transition: all 0.3s ease;\n        width: 35px;\n      }\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Sidebar Collapsed\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .sidebar {\n    @include from($breakpoint-xl) {\n      width: $collapsed-size;\n\n      .sidebar-inner {\n        .sidebar-logo {\n          border-bottom: 1px solid transparent;\n          padding: 0;\n        }\n\n        .sidebar-menu {\n          overflow-x: hidden;\n\n          > li {\n            > a {\n              .title {\n                display: none;\n              }\n            }\n          }\n\n          li {\n            &.dropdown {\n              .arrow {\n                opacity: 0;\n              }\n\n              &.open {\n                ul.dropdown-menu {\n                  display: none !important;\n                }\n              }\n            }\n          }\n        }\n      }\n\n      &:hover {\n        width: $offscreen-size;\n\n        .sidebar-inner {\n          .sidebar-logo {\n            border-bottom: 1px solid $border-color;\n            padding: 0 20px;\n          }\n\n          .sidebar-menu {\n            > li {\n              > a {\n                .title {\n                  display: inline-block;\n                }\n              }\n            }\n\n            li {\n              &.dropdown {\n                .arrow {\n                  opacity: 1;\n                }\n              }\n\n              &.open {\n                > ul.dropdown-menu {\n                  display: block !important;\n                }\n              }\n            }\n          }\n        }\n      }\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      width: $offscreen-size;\n\n      .sidebar-inner {\n        .sidebar-logo {\n          border-bottom: 1px solid $border-color;\n          padding: 0 20px;\n\n          > a {\n            .logo {\n              background-position: center left;\n              width: 150px;\n            }\n          }\n        }\n\n        .sidebar-menu {\n          > li {\n            > a {\n              .title {\n                display: inline-block;\n              }\n            }\n          }\n\n          li {\n            &.dropdown {\n              .arrow {\n                opacity: 1;\n              }\n            }\n\n            &.open {\n              > ul.dropdown-menu {\n                display: block !important;\n              }\n            }\n          }\n        }\n      }\n    }\n\n    @include to($breakpoint-md) {\n      left: 0;\n    }\n  }\n}\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @General Media Query\n// + @All Above Media Query\n// + @All Under Media Query\n// + @Between Two Devices Media Query\n\n// ---------------------------------------------------------\n// @General Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used for custom rules that don't follow\n// any of the following premade media queries.\n\n@mixin mq($condition) {\n  @media #{$condition} {\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @All Above Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match certain breakpoint\n// and all devices above it.\n\n@mixin from($breakpoint) {\n  @media screen and (min-width: $breakpoint){\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @All Under Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match all devices under certain breakpoint.\n\n@mixin to($breakpoint) {\n  @media screen and (max-width: $breakpoint - 1px) {\n    @content;\n  }\n}\n\n// ---------------------------------------------------------\n// @Between Two Devices Media Query Mixin\n// ---------------------------------------------------------\n\n// Mixin used to match the devices between 2 breakpoints.\n\n@mixin between($start, $end){\n  @media screen and (min-width: $start) and (max-width: $end - 1px) {\n    @content;\n  }\n}\n","// ---------------------------------------------------------\n// @TOC\n\n// + @Topbar\n// + @Collapsed State\n\n// ---------------------------------------------------------\n// @Topbar\n// ---------------------------------------------------------\n\n.header {\n  background-color: $default-white;\n  border-bottom: 1px solid $border-color;\n  display: block;\n  margin-bottom: 0;\n  padding: 0;\n  position: fixed;\n  transition: all 0.2s ease;\n  width: calc(100% - #{$offscreen-size});\n  z-index: 800;\n\n  @include to($breakpoint-md) {\n    width: 100%;\n  }\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    width: calc(100% - #{$collapsed-size});\n  }\n\n  .header-container {\n    @include clearfix;\n\n    height: $header-height;\n\n    .nav-left,\n    .nav-right {\n      list-style: none;\n      margin-bottom: 0;\n      padding-left: 0;\n      position: relative;\n\n      > li {\n        float: left;\n\n        > a {\n          color: $default-text-color;\n          display: block;\n          line-height: $header-height;\n          min-height: $header-height;\n          padding: 0 15px;\n          transition: all 0.2s ease-in-out;\n\n          i {\n            font-size: 17px;\n          }\n\n          &:hover,\n          &:focus {\n            color: $default-dark;\n            text-decoration: none;\n          }\n\n          @include to($breakpoint-md) {\n            padding: 0 15px;\n          }\n        }\n      }\n\n      .notifications {\n        position: relative;\n\n        .counter {\n          background-color: $default-danger;\n          border-radius: 50px;\n          color: $default-white;\n          font-size: 10px;\n          line-height: 1;\n          padding: 3px 5.5px;\n          position: absolute;\n          right: 6px;\n          top: 12px;\n        }\n\n        .dropdown-menu {\n          min-width: 350px;\n          padding: 0;\n\n          @include to($breakpoint-sm) {\n            max-width: 300px;\n          }\n        }\n      }\n    }\n\n    .dropdown-menu {\n      // display: block;\n      margin: 0;\n      transform-origin: top right;\n      // transform: scale(0, 0);\n      transition: transform 0.15s ease-out;\n\n      .divider {\n        border-bottom: 1px solid $border-color;\n        height: 1px;\n        overflow: hidden;\n      }\n\n      > li {\n        > a {\n          transition: all 0.2s ease-out;\n        }\n      }\n    }\n\n    .show {\n      .dropdown-menu {\n        transform: scale(1, 1);\n      }\n    }\n\n    .nav-left {\n      float: left;\n      margin-left: 15px;\n    }\n\n    .nav-right {\n      float: right;\n\n      .dropdown-menu {\n        left: auto;\n        right: 0;\n\n        > li {\n          width: 100%;\n\n          > a {\n            line-height: 1.5;\n            min-height: auto;\n            padding: 10px 15px;\n          }\n        }\n      }\n    }\n  }\n\n  .search-box {\n    .search-icon-close {\n      display: none;\n    }\n\n    &.active {\n      .search-icon {\n        display: none;\n      }\n\n      .search-icon-close {\n        display: inline-block;\n      }\n    }\n  }\n\n  .search-input {\n    display: none;\n\n    &.active {\n      display: inline-block;\n    }\n\n    input {\n      background-color: transparent;\n      border: 0;\n      box-shadow: none;\n      font-size: 18px;\n      height: 40px;\n      margin-top: 12px;\n      outline: none;\n      padding: 5px;\n\n      @include to($breakpoint-sm) {\n        width: 85px;\n      }\n\n      @include placeholder {\n        color: lighten($default-text-color, 20%);\n        font-style: italic;\n      }\n    }\n  }\n}\n\n// ---------------------------------------------------------\n// @Collapsed State\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .header {\n    width: calc(100% - #{$collapsed-size});\n\n    @include to($breakpoint-md) {\n      width: 100%;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      width: calc(100% - #{$offscreen-size});\n    }\n  }\n}\n","//----------------------------------------------------------\n// @Placeholder\n//----------------------------------------------------------\n\n@mixin placeholder {\n  &::-webkit-input-placeholder { @content; }\n  &:-moz-placeholder { @content; }\n  &::-moz-placeholder { @content; }\n  &:-ms-input-placeholder { @content; }\n}\n","// ---------------------------------------------------------\n// @TOC\n// ---------------------------------------------------------\n\n// + @Page Container\n// + @Main Content\n// + @Full Container\n// + @Collapsed State\n\n// ---------------------------------------------------------\n// @Page Container\n// ---------------------------------------------------------\n\n.page-container {\n  min-height: 100vh;\n  padding-left: $offscreen-size;\n  transition: all 0.2s ease;\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    padding-left: $collapsed-size;\n  }\n\n  @include to($breakpoint-md) {\n    padding-left: 0;\n  }\n}\n\n// ---------------------------------------------------------\n// @Main Content\n// ---------------------------------------------------------\n\n.main-content {\n  padding: 85px 20px 20px;\n  min-height: calc(100vh - 61px);\n\n  @include to($breakpoint-md) {\n    padding: 85px 5px 5px;\n  }\n}\n\n.remain-height {\n  height: calc(100vh - 126px);\n}\n\n// ---------------------------------------------------------\n// @Full Container\n// ---------------------------------------------------------\n\n.full-container {\n  left: $offscreen-size;\n  min-height: calc(100vh - #{$header-height});\n  position: absolute;\n  right: 0;\n  top: $header-height;\n  transition: all 0.2s ease;\n\n  @include between($breakpoint-md, $breakpoint-xl) {\n    left: 0;\n    padding-left: $collapsed-size;\n  }\n\n  @include to($breakpoint-md) {\n    left: 0;\n  }\n}\n\n// ---------------------------------------------------------\n// @Collapsed State\n// ---------------------------------------------------------\n\n.is-collapsed {\n  .page-container {\n    padding-left: $collapsed-size;\n\n    @include to($breakpoint-md) {\n      padding-left: 0;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      padding-left: $offscreen-size;\n    }\n  }\n\n  .full-container {\n    left: $collapsed-size;\n\n    @include to($breakpoint-md) {\n      left: 0;\n    }\n\n    @include between($breakpoint-md, $breakpoint-xl) {\n      left: $offscreen-size;\n      padding-left: 0;\n    }\n  }\n}\n",".progress {\n  height: 4px;\n  background-color: #eaeef3;\n  border-radius: 4px;\n  margin-bottom: 10px;\n}\n",".easy-pie-chart {\n  position: relative;\n\n  span {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    line-height: 0;\n  }\n}\n",".checkbox label {\n  display: inline-block;\n  vertical-align: middle;\n  position: relative;\n  padding-left: 17px;\n  margin-bottom: 0;\n}\n\n.checkbox label::before {\n  content: \"\";\n  display: inline-block;\n  position: absolute;\n  width: 17px;\n  height: 17px;\n  left: 0;\n  top: 50%;\n  transform: translateY(-50%);\n  margin-left: -12px;\n  border: 1px solid $grey-300;\n  border-radius: 3px;\n  background-color: $md-white;\n  -webkit-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n  -o-transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n  transition: border 0.15s ease-in-out, color 0.15s ease-in-out;\n}\n\n.checkbox label::after {\n  display: inline-block;\n  position: absolute;\n  width: 17px;\n  height: 17px;\n  text-align: center;\n  font-size: 10px !important;\n  line-height: 17px;\n  left: 0;\n  top: 50%;\n  transform: translateY(-50%);\n  margin-left: -12px;\n  color: $grey-500;\n}\n\n.checkbox input[type=\"checkbox\"] {\n  opacity: 0;\n  z-index: 1;\n}\n\n.checkbox input[type=\"checkbox\"]:focus + label::before {\n  outline: thin dotted;\n  outline: 5px auto -webkit-focus-ring-color;\n  outline-offset: -2px;\n}\n\n.checkbox input[type=\"checkbox\"]:checked + label::after {\n  font-family: 'FontAwesome';\n  cont